  useEffect(() => {if ("'!notice) return; const timer = window.setTimeout(() => setNotice('"''), 4500); return () => window.clearTimeout(timer);}, [notice]);
  const words = body.trim() ? body.trim().split(/\\s+/u).length : 0;
